parameters.text:
=You are scoring and tailoring a job application for the candidate below.

THRESHOLD: {{ $('Load Config1').first().json.threshold }}

Do the following:
1. Score 0-100 how well the candidate fits this job, and give a one-sentence reason.
2. Only if the score is >= THRESHOLD, also write:
   - cover_letter: a concise, tailored cover letter (max 200 words)
   - bullets: 3-5 tailored resume bullet points mapping the candidate's real experience to this job
   If the score is below THRESHOLD, set cover_letter to "" and bullets to [].

=== CANDIDATE CV ===
{{ $('Load Config1').first().json.cvText }}

=== JOB ===
Title: {{ $json.title }}
Company: {{ $json.company }}
Location: {{ $json.location }}
Description: {{ $json.description }}

parameters.jsCode:
const a = $json.output || {};
const j = $('Deduplicate Jobs1').item.json;
const bullets = Array.isArray(a.bullets) ? a.bullets : [];
return { json: {
  date: new Date().toISOString().slice(0, 10),
  source: j.source || '',
  title: j.title || '',
  company: j.company || '',
  location: j.location || '',
  url: j.url || '',
  score: Number(a.score) || 0,
  reason: a.reason || '',
  cover_letter: a.cover_letter || '',
  cv_bullets: bullets.map((b, i) => (i + 1) + '. ' + b).join('\n'),
  status: 'To review'
}};

const results = ($input.first().json.results) || [];
return results.map(r => ({ json: {
  source: 'Adzuna',
  title: r.title || '',
  company: (r.company && r.company.display_name) || '',
  location: (r.location && r.location.display_name) || '',
  url: r.redirect_url || '',
  description: String(r.description || '').slice(0, 2000)
}}));

let entries = $input.all().map(i => i.json);
if (entries.length === 1 && Array.isArray(entries[0])) entries = entries[0];
return entries
  .filter(e => e && e.position && e.url)
  .map(e => ({ json: {
    source: 'RemoteOK',
    title: e.position,
    company: e.company || '',
    location: e.location || 'Remote',
    url: e.url,
    description: String(e.description || '').replace(/<[^>]+>/g, ' ').slice(0, 2000),
    tags: e.tags || []
  }}))
  .filter(o => /ai|ml|machine learning|data|llm|agent/i.test(o.json.title + ' ' + (o.json.tags || []).join(' ')))
  .map(o => { delete o.json.tags; return o; });

const staticData = $getWorkflowStaticData('global');
const seen = new Set(staticData.seenUrls || []);
const out = [];
for (const it of $input.all()) {
  const u = it.json.url;
  if (u && !seen.has(u)) { seen.add(u); out.push(it); }
}
staticData.seenUrls = Array.from(seen).slice(-5000);
return out;
